var import_obsidian5 = require("obsidian");
init_BaiduSyncService();
var BaiduSyncModal = class extends import_obsidian5.Modal {
  constructor(app, config, onSaveToken) {
    super(app);
    this.config = config;
    this.onSaveToken = onSaveToken;
    this.mode = "sync";
    this.folder = "";
    this.overwrite = false;
    this.conflictStrategy = "keep-both";
    this.deleteRemoteOnLocalDelete = false;
    this.titleEl.setText("\u767E\u5EA6\u7F51\u76D8\u540C\u6B65");
  }
  onOpen() {
    const { contentEl } = this;
    new import_obsidian5.Setting(contentEl).setName("\u64CD\u4F5C\u6A21\u5F0F").addDropdown(
      (drop) => drop.addOption("sync", "\u53CC\u5411\u540C\u6B65\uFF08\u63A8\u8350\uFF09").addOption("backup", "\u4EC5\u5907\u4EFD\u5230\u767E\u5EA6\u4E91").addOption("restore", "\u4EC5\u4ECE\u767E\u5EA6\u4E91\u6062\u590D").addOption("force-restore", "\u26A0\uFE0F \u5F3A\u5236\u8986\u76D6\u672C\u5730\uFF08\u4EE5\u4E91\u7AEF\u4E3A\u51C6\uFF09").setValue(this.mode).onChange((v) => {
        this.mode = v;
        this.refresh();
      })
    );
    new import_obsidian5.Setting(contentEl).setName("\u76EE\u5F55\u8303\u56F4").setDesc("\u7559\u7A7A\u8868\u793A\u6574\u4E2A Vault\uFF1B\u586B\u5199\u76F8\u5BF9\u8DEF\u5F84\u5982 Knowledge/Q&A \u5219\u53EA\u540C\u6B65\u8BE5\u76EE\u5F55").addText(
      (text) => text.setPlaceholder("Knowledge/Q&A").setValue(this.folder).onChange((v) => this.folder = v.trim())
    );
    if (this.mode === "sync") {
      new import_obsidian5.Setting(contentEl).setName("\u51B2\u7A81\u5904\u7406").setDesc("\u4E24\u7AEF\u90FD\u4FEE\u6539\u4E86\u540C\u4E00\u6587\u4EF6\u65F6\u7684\u5904\u7406\u65B9\u5F0F").addDropdown(
        (drop) => drop.addOption("keep-both", "\u4FDD\u7559\u4E24\u4EFD\uFF08\u672C\u5730\u52A0 .conflict \u540E\u7F00\uFF09").addOption("local", "\u4EE5\u672C\u5730\u4E3A\u51C6").addOption("remote", "\u4EE5\u8FDC\u7AEF\u4E3A\u51C6").setValue(this.conflictStrategy).onChange((v) => this.conflictStrategy = v)
      );
      new import_obsidian5.Setting(contentEl).setName("\u672C\u5730\u5220\u9664\u65F6\u540C\u6B65\u5220\u9664\u8FDC\u7AEF").setDesc("\u5F00\u542F\u540E\uFF0C\u672C\u5730\u5220\u9664\u7684\u6587\u4EF6\u4E5F\u4F1A\u4ECE\u767E\u5EA6\u4E91\u5220\u9664").addToggle(
        (t) => t.setValue(this.deleteRemoteOnLocalDelete).onChange((v) => this.deleteRemoteOnLocalDelete = v)
      );
    }
    if (this.mode === "restore") {
      new import_obsidian5.Setting(contentEl).setName("\u8986\u76D6\u672C\u5730\u6587\u4EF6").setDesc("\u5F00\u542F\u540E\uFF0C\u8FDC\u7AEF\u6587\u4EF6\u5C06\u8986\u76D6\u672C\u5730\u540C\u540D\u6587\u4EF6").addToggle((t) => t.setValue(this.overwrite).onChange((v) => this.overwrite = v));
    }
    if (this.mode === "force-restore") {
      contentEl.createEl("p", {
        text: "\u26A0\uFE0F \u5F3A\u5236\u8986\u76D6\u5C06\u5220\u9664\u672C\u5730\u6307\u5B9A\u76EE\u5F55\u4E0B\u7684\u6240\u6709\u6587\u4EF6\uFF0C\u7136\u540E\u4ECE\u4E91\u7AEF\u5B8C\u6574\u6062\u590D\u3002\u6B64\u64CD\u4F5C\u4E0D\u53EF\u64A4\u9500\uFF01",
        cls: "istart-sync-modal-warning"
      });
    }
    contentEl.createEl("p", {
      text: `\u8FDC\u7AEF\u8DEF\u5F84\uFF1A${this.config.remotePath}/${this.folder || "(vault root)"}`,
      cls: "istart-sync-modal-remote-path"
    });
    const modeLabels = {
      sync: "\u5F00\u59CB\u540C\u6B65",
      backup: "\u5F00\u59CB\u5907\u4EFD",
      restore: "\u5F00\u59CB\u6062\u590D",
      "force-restore": "\u26A0\uFE0F \u786E\u8BA4\u5F3A\u5236\u8986\u76D6"
    };
    new import_obsidian5.Setting(contentEl).addButton(
      (btn) => btn.setButtonText(modeLabels[this.mode]).setCta().onClick(() => this.run())
    ).addButton((btn) => btn.setButtonText("\u53D6\u6D88").onClick(() => this.close()));
  }
  refresh() {
    this.contentEl.empty();
    this.onOpen();
  }
  async run() {
    this.close();
    const service = new BaiduSyncService(this.app, this.config);
    const tokenOk = await service.ensureValidToken();
    if (!tokenOk) {
      new import_obsidian5.Notice("\u274C Token \u5DF2\u8FC7\u671F\uFF0C\u8BF7\u91CD\u65B0\u6388\u6743");
      return;
    }
    await this.onSaveToken(this.config.accessToken, this.config.tokenExpiresAt);
    if (this.mode === "sync") {
      await this.runSync(service);
    } else if (this.mode === "backup") {
      await this.runBackup(service);
    } else if (this.mode === "force-restore") {
      await this.runForceRestore(service);
    } else {
      await this.runRestore(service);
    }
  }
  async runSync(service) {
    const notice = new import_obsidian5.Notice("\u23F3 \u540C\u6B65\u4E2D...", 0);
    const result = await service.sync(
      this.folder,
      { conflictStrategy: this.conflictStrategy, deleteRemoteOnLocalDelete: this.deleteRemoteOnLocalDelete },
      (msg) => notice.setMessage(`\u23F3 ${msg}`)
    );
    notice.hide();
    const parts = [
      result.uploaded > 0 && `\u2191 ${result.uploaded}`,
      result.downloaded > 0 && `\u2193 ${result.downloaded}`,
      result.conflicts.length > 0 && `\u26A0\uFE0F \u51B2\u7A81 ${result.conflicts.length}`,
      result.deleted > 0 && `\u{1F5D1} ${result.deleted}`,
      result.failed > 0 && `\u274C \u5931\u8D25 ${result.failed}`
    ].filter(Boolean).join("  ");
    new import_obsidian5.Notice(parts ? `\u2705 \u540C\u6B65\u5B8C\u6210  ${parts}` : "\u2705 \u5DF2\u662F\u6700\u65B0\uFF0C\u65E0\u9700\u540C\u6B65");
    if (result.errors.length > 0) {
      console.error("[IStart-Note-AI] \u540C\u6B65\u9519\u8BEF\uFF1A", result.errors);
    }
  }
  async runBackup(service) {
    const notice = new import_obsidian5.Notice("\u23F3 \u5907\u4EFD\u4E2D...", 0);
    const result = await service.backup(this.folder, (c, t, file) => {
      notice.setMessage(`\u23F3 \u5907\u4EFD\u4E2D (${c}/${t})\uFF1A${file.split("/").pop()}`);
    });
    notice.hide();
    new import_obsidian5.Notice(
      result.failed > 0 ? `\u26A0\uFE0F \u5907\u4EFD\u5B8C\u6210\uFF0C\u2191 ${result.uploaded}\uFF0C\u8DF3\u8FC7 ${result.skipped}\uFF0C\u5931\u8D25 ${result.failed}` : `\u2705 \u5907\u4EFD\u5B8C\u6210\uFF0C\u2191 ${result.uploaded}\uFF0C\u8DF3\u8FC7 ${result.skipped}`
    );
    if (result.errors.length > 0)
      console.error("[IStart-Note-AI] \u5907\u4EFD\u9519\u8BEF\uFF1A", result.errors);
  }
  async runRestore(service) {
    const notice = new import_obsidian5.Notice("\u23F3 \u6062\u590D\u4E2D...", 0);
    const result = await service.restore(this.folder, this.overwrite, (c, t, file) => {
      notice.setMessage(`\u23F3 \u6062\u590D\u4E2D (${c}/${t})\uFF1A${file.split("/").pop()}`);
    });
    notice.hide();
    new import_obsidian5.Notice(
      result.failed > 0 ? `\u26A0\uFE0F \u6062\u590D\u5B8C\u6210\uFF0C\u2193 ${result.downloaded}\uFF0C\u8DF3\u8FC7 ${result.skipped}\uFF0C\u5931\u8D25 ${result.failed}` : `\u2705 \u6062\u590D\u5B8C\u6210\uFF0C\u2193 ${result.downloaded}\uFF0C\u8DF3\u8FC7 ${result.skipped}`
    );
    if (result.errors.length > 0)
      console.error("[IStart-Note-AI] \u6062\u590D\u9519\u8BEF\uFF1A", result.errors);
  }
  async runForceRestore(service) {
    const notice = new import_obsidian5.Notice("\u23F3 \u5F3A\u5236\u8986\u76D6\uFF1A\u6E05\u7406\u672C\u5730\u6587\u4EF6...", 0);
    const files = this.app.vault.getFiles();
    const targetFiles = this.folder ? files.filter((f) => f.path.startsWith(this.folder)) : files.filter((f) => !f.path.split("/").some((p) => p.startsWith(".")));
    for (const f of targetFiles) {
      try {
        await this.app.vault.delete(f);
      } catch (e) {
      }
    }
    notice.setMessage("\u23F3 \u5F3A\u5236\u8986\u76D6\uFF1A\u4ECE\u4E91\u7AEF\u6062\u590D...");
    const result = await service.restore(this.folder, true, (c, t, file) => {
      notice.setMessage(`\u23F3 \u6062\u590D\u4E2D (${c}/${t})\uFF1A${file.split("/").pop()}`);
    });
    notice.hide();
    new import_obsidian5.Notice(
      `\u2705 \u5F3A\u5236\u8986\u76D6\u5B8C\u6210\uFF1A\u5220\u9664\u672C\u5730 ${targetFiles.length} \u4E2A\u6587\u4EF6\uFF0C\u4ECE\u4E91\u7AEF\u6062\u590D ${result.downloaded} \u4E2A\u6587\u4EF6`
    );
    if (this.config.backupPlugin) {
      const pluginResult = await service.restorePlugin();
      if (pluginResult.downloaded > 0) {
        new import_obsidian5.Notice(`\u2705 \u63D2\u4EF6\u6587\u4EF6\u5DF2\u6062\u590D\uFF08${pluginResult.downloaded} \u4E2A\u6587\u4EF6\uFF09\uFF0C\u8BF7\u91CD\u542F Obsidian`);
      }
    }
  }
  onClose() {
    this.contentEl.empty();
  }
};

