init_BaiduSyncService();
init_BaiduSyncMeta();
init_BaiduPanClient();
var SYNC_VIEW_TYPE = "istart-baidu-sync-view";
var BaiduSyncView = class extends import_obsidian6.ItemView {
  constructor(leaf, plugin) {
    super(leaf);
    this.statusList = [];
    this.isScanning = false;
    this.lastScanTime = null;
    this.plugin = plugin;
  }
  getViewType() {
    return SYNC_VIEW_TYPE;
  }
  getDisplayText() {
    return "\u767E\u5EA6\u4E91\u540C\u6B65\u72B6\u6001";
  }
  getIcon() {
    return "cloud";
  }
  onOpen() {
    this.render();
    return Promise.resolve();
  }
  onClose() {
    return Promise.resolve();
  }
  // ── 渲染 ───────────────────────────────────────────────────
  render() {
    const root = this.containerEl.children[1];
    root.empty();
    root.addClass("istart-sync-root");
    const header = root.createDiv({ cls: "istart-sync-header" });
    header.createEl("h4", { text: "\u767E\u5EA6\u4E91\u540C\u6B65\u72B6\u6001" });
    const cfg = this.plugin.settings.baiduSync;
    if (!cfg.enabled || !cfg.accessToken) {
      root.createEl("p", {
        text: "\u8BF7\u5148\u5728\u8BBE\u7F6E\u4E2D\u542F\u7528\u767E\u5EA6\u4E91\u540C\u6B65\u5E76\u5B8C\u6210\u6388\u6743\u3002",
        cls: "istart-sync-hint"
      });
      return;
    }
    const btnRow = root.createDiv({ cls: "istart-sync-btn-row" });
    this.makeBtn(btnRow, "\u{1F50D} \u626B\u63CF\u72B6\u6001", "default", () => {
      void this.scan();
    });
    this.makeBtn(btnRow, "\u2B06 \u5F3A\u5236\u5907\u4EFD", "default", () => {
      void this.forceBackup();
    });
    this.makeBtn(btnRow, "\u2B07 \u5F3A\u5236\u66F4\u65B0", "default", () => {
      void this.forceUpdate();
    });
    this.makeBtn(btnRow, "\u21C4 \u53CC\u5411\u540C\u6B65", "cta", () => {
      void this.runSync();
    });
    this.makeBtn(btnRow, "\u26A0\uFE0F \u5F3A\u5236\u8986\u76D6", "default", () => {
      void this.forceOverwrite();
    });
    if (this.lastScanTime) {
      root.createEl("p", {
        text: `\u4E0A\u6B21\u626B\u63CF\uFF1A${this.lastScanTime.toLocaleTimeString()}`,
        cls: "istart-sync-scan-time"
      });
    }
    if (this.isScanning) {
      root.createEl("p", { text: "\u23F3 \u626B\u63CF\u4E2D...", cls: "istart-sync-status-msg" });
      return;
    }
    if (this.statusList.length === 0 && this.lastScanTime) {
      root.createEl("p", { text: "\u2705 \u5DF2\u662F\u6700\u65B0\uFF0C\u65E0\u9700\u540C\u6B65", cls: "istart-sync-success" });
      return;
    }
    if (this.statusList.length === 0) {
      root.createEl("p", { text: "\u70B9\u51FB\u300C\u626B\u63CF\u72B6\u6001\u300D\u67E5\u770B\u540C\u6B65\u60C5\u51B5", cls: "istart-sync-hint" });
      return;
    }
    const counts = this.countByAction();
    const summaryEl = root.createDiv({ cls: "istart-sync-summary" });
    if (counts.upload)
      this.makeBadge(summaryEl, `\u2191 ${counts.upload} \u5F85\u4E0A\u4F20`, "istart-sync-badge-upload");
    if (counts.download)
      this.makeBadge(summaryEl, `\u2193 ${counts.download} \u5F85\u4E0B\u8F7D`, "istart-sync-badge-download");
    if (counts.conflict)
      this.makeBadge(summaryEl, `\u26A0 ${counts.conflict} \u51B2\u7A81`, "istart-sync-badge-conflict");
    if (counts.unchanged)
      this.makeBadge(summaryEl, `\u2713 ${counts.unchanged} \u5DF2\u540C\u6B65`, "istart-sync-badge-unchanged");
    const actionItems = this.statusList.filter((s) => s.action !== "unchanged" /* Unchanged */);
    if (actionItems.length === 0) {
      root.createEl("p", { text: "\u2705 \u6240\u6709\u6587\u4EF6\u5DF2\u540C\u6B65", cls: "istart-sync-success" });
      return;
    }
    const listEl = root.createDiv();
    for (const item of actionItems) {
      this.renderFileRow(listEl, item);
    }
  }
  renderFileRow(container, item) {
    var _a;
    const row = container.createDiv({ cls: "istart-sync-file-row" });
    const left = row.createDiv({ cls: "istart-sync-file-left" });
    left.createSpan({ text: this.actionIcon(item.action), cls: "istart-sync-file-icon" });
    left.createSpan({
      text: (_a = item.path.split("/").pop()) != null ? _a : item.path,
      cls: "istart-sync-file-name",
      attr: { title: item.path }
    });
    const right = row.createDiv({ cls: "istart-sync-file-actions" });
    if (item.action === "upload" /* Upload */ || item.action === "local-only" /* LocalOnly */) {
      this.makeSmallBtn(right, "\u4E0A\u4F20", () => {
        void this.uploadOne(item.path);
      });
    }
    if (item.action === "download" /* Download */ || item.action === "remote-only" /* RemoteOnly */) {
      this.makeSmallBtn(right, "\u4E0B\u8F7D", () => {
        void this.downloadOne(item);
      });
    }
    if (item.action === "conflict" /* Conflict */) {
      this.makeSmallBtn(right, "\u7528\u672C\u5730", () => {
        void this.resolveConflict(item, "local");
      });
      this.makeSmallBtn(right, "\u7528\u8FDC\u7AEF", () => {
        void this.resolveConflict(item, "remote");
      });
    }
    if (item.action === "local-deleted" /* LocalDeleted */) {
      this.makeSmallBtn(right, "\u5220\u8FDC\u7AEF", () => {
        void this.deleteRemote(item.path);
      });
    }
  }
  // ── 操作 ───────────────────────────────────────────────────
  async scan() {
    const cfg = this.plugin.settings.baiduSync;
    if (!cfg.enabled || !cfg.accessToken)
      return;
    this.isScanning = true;
    this.render();
    try {
      const service = new BaiduSyncService(this.app, cfg);
      const tokenOk = await service.ensureValidToken();
      if (!tokenOk) {
        new import_obsidian6.Notice("Token \u5DF2\u8FC7\u671F\uFF0C\u8BF7\u91CD\u65B0\u6388\u6743");
        return;
      }
      await this.plugin.saveSettings();
      const client = new BaiduPanClient(cfg);
      const remoteRoot = cfg.remotePath;
      const metaPath = `${cfg.remotePath}/istart-sync-meta.json`;
      let meta = new BaiduSyncMeta();
      try {
        const metaBuf = await client.downloadFile(metaPath);
        if (metaBuf)
          meta = new BaiduSyncMeta(new TextDecoder().decode(metaBuf));
      } catch (e) {
      }
      const localMap = /* @__PURE__ */ new Map();
      for (const f of this.app.vault.getFiles()) {
        if (!f.path.split("/").some((p) => p.startsWith("."))) {
          localMap.set(f.path, f.stat.mtime);
        }
      }
      const remoteMap = /* @__PURE__ */ new Map();
      const remoteEntries = await client.listAllFiles(remoteRoot);
      for (const e of remoteEntries) {
        if (!e.isdir && !e.path.endsWith("istart-sync-meta.json")) {
          const rel = e.path.replace(remoteRoot + "/", "").replace(/^\//, "");
          remoteMap.set(rel, e.server_mtime);
        }
      }
      const plans = meta.buildSyncPlan(localMap, remoteMap);
      this.statusList = plans.map((p) => ({
        path: p.path,
        action: p.action,
        localMtime: p.localMtime,
        remoteMtime: p.remoteMtime
      }));
      this.lastScanTime = new Date();
    } catch (e) {
      new import_obsidian6.Notice("\u626B\u63CF\u5931\u8D25\uFF1A" + e.message);
    } finally {
      this.isScanning = false;
      this.render();
    }
  }
  async forceBackup() {
    const cfg = this.plugin.settings.baiduSync;
    const service = new BaiduSyncService(this.app, cfg);
    const tokenOk = await service.ensureValidToken();
    if (!tokenOk) {
      new import_obsidian6.Notice("Token \u5DF2\u8FC7\u671F\uFF0C\u8BF7\u91CD\u65B0\u6388\u6743");
      return;
    }
    const notice = new import_obsidian6.Notice("\u23F3 \u5F3A\u5236\u5907\u4EFD\u4E2D...", 0);
    const result = await service.backup(
      "",
      (c, t, f) => notice.setMessage(`\u23F3 \u5907\u4EFD (${c}/${t})\uFF1A${f.split("/").pop()}`)
    );
    notice.hide();
    new import_obsidian6.Notice(`\u2705 \u5907\u4EFD\u5B8C\u6210\uFF0C\u2191 ${result.uploaded}\uFF0C\u8DF3\u8FC7 ${result.skipped}\uFF0C\u5931\u8D25 ${result.failed}`);
    await this.scan();
  }
  async forceUpdate() {
    const cfg = this.plugin.settings.baiduSync;
    const service = new BaiduSyncService(this.app, cfg);
    const tokenOk = await service.ensureValidToken();
    if (!tokenOk) {
      new import_obsidian6.Notice("Token \u5DF2\u8FC7\u671F\uFF0C\u8BF7\u91CD\u65B0\u6388\u6743");
      return;
    }
    const notice = new import_obsidian6.Notice("\u23F3 \u5F3A\u5236\u66F4\u65B0\u4E2D...", 0);
    const result = await service.restore(
      "",
      true,
      (c, t, f) => notice.setMessage(`\u23F3 \u66F4\u65B0 (${c}/${t})\uFF1A${f.split("/").pop()}`)
    );
    notice.hide();
    new import_obsidian6.Notice(`\u2705 \u66F4\u65B0\u5B8C\u6210\uFF0C\u2193 ${result.downloaded}\uFF0C\u8DF3\u8FC7 ${result.skipped}\uFF0C\u5931\u8D25 ${result.failed}`);
    await this.scan();
  }
  async runSync() {
    const cfg = this.plugin.settings.baiduSync;
    const service = new BaiduSyncService(this.app, cfg);
    const tokenOk = await service.ensureValidToken();
    if (!tokenOk) {
      new import_obsidian6.Notice("Token \u5DF2\u8FC7\u671F\uFF0C\u8BF7\u91CD\u65B0\u6388\u6743");
      return;
    }
    const notice = new import_obsidian6.Notice("\u23F3 \u540C\u6B65\u4E2D...", 0);
    const result = await service.sync(
      "",
      { conflictStrategy: "keep-both" },
      (msg) => notice.setMessage(`\u23F3 ${msg}`)
    );
    notice.hide();
    const parts = [
      result.uploaded && `\u2191 ${result.uploaded}`,
      result.downloaded && `\u2193 ${result.downloaded}`,
      result.conflicts.length && `\u26A0 \u51B2\u7A81 ${result.conflicts.length}`,
      result.failed && `\u274C ${result.failed}`
    ].filter(Boolean).join("  ");
    new import_obsidian6.Notice(parts ? `\u2705 \u540C\u6B65\u5B8C\u6210  ${parts}` : "\u2705 \u5DF2\u662F\u6700\u65B0");
    await this.scan();
  }
  async forceOverwrite() {
    const cfg = this.plugin.settings.baiduSync;
    const service = new BaiduSyncService(this.app, cfg);
    const tokenOk = await service.ensureValidToken();
    if (!tokenOk) {
      new import_obsidian6.Notice("Token \u5DF2\u8FC7\u671F\uFF0C\u8BF7\u91CD\u65B0\u6388\u6743");
      return;
    }
    const confirmed = await new Promise((resolve) => {
      const modal = new class extends require("obsidian").Modal {
        onOpen() {
          this.titleEl.setText("\u26A0\uFE0F \u786E\u8BA4\u5F3A\u5236\u8986\u76D6");
          this.contentEl.createEl("p", {
            text: "\u6B64\u64CD\u4F5C\u5C06\u5220\u9664\u672C\u5730\u6240\u6709\u540C\u6B65\u6587\u4EF6\uFF0C\u7136\u540E\u4ECE\u4E91\u7AEF\u5B8C\u6574\u6062\u590D\u3002\u4E0D\u53EF\u64A4\u9500\uFF01",
            cls: "istart-sync-modal-warning"
          });
          const { Setting: Setting12 } = require("obsidian");
          new Setting12(this.contentEl).addButton((btn) => btn.setButtonText("\u786E\u8BA4\u8986\u76D6").setWarning().onClick(() => {
            this.close();
            resolve(true);
          })).addButton((btn) => btn.setButtonText("\u53D6\u6D88").onClick(() => {
            this.close();
            resolve(false);
          }));
        }
        onClose() {
          this.contentEl.empty();
          resolve(false);
        }
      }(this.app);
      modal.open();
    });
    if (!confirmed)
      return;
    const notice = new import_obsidian6.Notice("\u23F3 \u5F3A\u5236\u8986\u76D6\uFF1A\u6E05\u7406\u672C\u5730...", 0);
    const files = this.app.vault.getFiles().filter(
      (f) => !f.path.split("/").some((p) => p.startsWith("."))
    );
    for (const f of files) {
      try {
        await this.app.vault.delete(f);
      } catch (e) {
      }
    }
    notice.setMessage("\u23F3 \u5F3A\u5236\u8986\u76D6\uFF1A\u4ECE\u4E91\u7AEF\u6062\u590D...");
    const result = await service.restore("", true, (c, t, file) => {
      notice.setMessage(`\u23F3 \u6062\u590D\u4E2D (${c}/${t})\uFF1A${file.split("/").pop()}`);
    });
    notice.hide();
    new import_obsidian6.Notice(`\u2705 \u5F3A\u5236\u8986\u76D6\u5B8C\u6210\uFF1A\u6062\u590D ${result.downloaded} \u4E2A\u6587\u4EF6`);
    await this.scan();
  }
  async uploadOne(path) {
    const cfg = this.plugin.settings.baiduSync;
    const abstract = this.app.vault.getAbstractFileByPath(path);
    if (!abstract || !(abstract instanceof import_obsidian6.TFile))
      return;
    const client = new BaiduPanClient(cfg);
    const content = await this.app.vault.readBinary(abstract);
    const remotePath = `${cfg.remotePath}/${path}`.replace(/\/+/g, "/");
    const ok = await client.uploadFile(content, remotePath);
    new import_obsidian6.Notice(ok ? `\u2705 \u5DF2\u4E0A\u4F20\uFF1A${path.split("/").pop()}` : `\u274C \u4E0A\u4F20\u5931\u8D25\uFF1A${path}`);
    if (ok)
      await this.scan();
  }
  async downloadOne(item) {
    const cfg = this.plugin.settings.baiduSync;
    const client = new BaiduPanClient(cfg);
    const remotePath = `${cfg.remotePath}/${item.path}`.replace(/\/+/g, "/");
    const content = await client.downloadFile(remotePath);
    if (!content) {
      new import_obsidian6.Notice(`\u274C \u4E0B\u8F7D\u5931\u8D25\uFF1A${item.path}`);
      return;
    }
    const dir = item.path.substring(0, item.path.lastIndexOf("/"));
    if (dir && !await this.app.vault.adapter.exists(dir))
      await this.app.vault.adapter.mkdir(dir);
    const existing = this.app.vault.getAbstractFileByPath(item.path);
    if (existing instanceof import_obsidian6.TFile)
      await this.app.vault.modifyBinary(existing, content);
    else
      await this.app.vault.createBinary(item.path, content);
    new import_obsidian6.Notice(`\u2705 \u5DF2\u4E0B\u8F7D\uFF1A${item.path.split("/").pop()}`);
    await this.scan();
  }
  async resolveConflict(item, strategy) {
    if (strategy === "local")
      await this.uploadOne(item.path);
    else
      await this.downloadOne(item);
  }
  async deleteRemote(path) {
    const cfg = this.plugin.settings.baiduSync;
    const client = new BaiduPanClient(cfg);
    const remotePath = `${cfg.remotePath}/${path}`.replace(/\/+/g, "/");
    const ok = await client.deleteFile(remotePath);
    new import_obsidian6.Notice(ok ? `\u2705 \u5DF2\u5220\u9664\u8FDC\u7AEF\uFF1A${path.split("/").pop()}` : `\u274C \u5220\u9664\u5931\u8D25`);
    if (ok)
      await this.scan();
  }
  // ── 工具方法 ───────────────────────────────────────────────
  countByAction() {
    const counts = { upload: 0, download: 0, conflict: 0, unchanged: 0 };
    for (const s of this.statusList) {
      if (s.action === "upload" /* Upload */ || s.action === "local-only" /* LocalOnly */)
        counts.upload++;
      else if (s.action === "download" /* Download */ || s.action === "remote-only" /* RemoteOnly */)
        counts.download++;
      else if (s.action === "conflict" /* Conflict */)
        counts.conflict++;
      else
        counts.unchanged++;
    }
    return counts;
  }
  actionIcon(action) {
    switch (action) {
      case "upload" /* Upload */:
      case "local-only" /* LocalOnly */:
        return "\u2191";
      case "download" /* Download */:
      case "remote-only" /* RemoteOnly */:
        return "\u2193";
      case "conflict" /* Conflict */:
        return "\u26A0";
      case "local-deleted" /* LocalDeleted */:
        return "\u{1F5D1}";
      case "remote-deleted" /* RemoteDeleted */:
        return "\u{1F5D1}";
      default:
        return "\u2713";
    }
  }
  makeBtn(container, text, type, onClick) {
    const btn = container.createEl("button", {
      text,
      cls: type === "cta" ? "istart-sync-btn-cta" : "istart-sync-btn"
    });
    btn.addEventListener("click", onClick);
  }
  makeSmallBtn(container, text, onClick) {
    const btn = container.createEl("button", { text, cls: "istart-sync-small-btn" });
    btn.addEventListener("click", onClick);
  }
  makeBadge(container, text, cls) {
    container.createSpan({ text, cls: `istart-sync-badge ${cls}` });
  }
};

