// src/ai/classifier/ContentClassifier.ts
var ContentClassifier = class {
  /**
   * 分类：返回最匹配的内容类型
   */
  classify(input) {
    const { instruction, fileName, filePath, fileType, selection } = input;
    const text = `${instruction} ${fileName} ${selection != null ? selection : ""}`.toLowerCase();
    if (fileType === "reading-note" || fileType === "reading-project")
      return "reading-note" /* READING_NOTE */;
    if (fileType === "concept")
      return "concept" /* CONCEPT */;
    if (fileType === "question")
      return "qa" /* QA */;
    if (filePath.includes("Reading/"))
      return "reading-note" /* READING_NOTE */;
    if (filePath.includes("Concepts/"))
      return "concept" /* CONCEPT */;
    if (filePath.includes("Q&A/"))
      return "qa" /* QA */;
    if (this.matchKeywords(text, ["\u67B6\u6784", "\u7CFB\u7EDF\u8BBE\u8BA1", "\u65B9\u6848\u8BBE\u8BA1", "\u6280\u672F\u9009\u578B", "\u5FAE\u670D\u52A1", "\u5206\u5E03\u5F0F"])) {
      return "architecture" /* ARCHITECTURE */;
    }
    if (this.matchKeywords(text, ["\u4EA7\u54C1", "\u9700\u6C42", "\u7528\u6237\u6545\u4E8B", "PRD", "\u529F\u80FD\u8BBE\u8BA1", "\u4EA4\u4E92"])) {
      return "product-design" /* PRODUCT_DESIGN */;
    }
    if (this.matchKeywords(text, ["\u4F1A\u8BAE", "\u8BA8\u8BBA", "\u51B3\u7B56", "\u884C\u52A8\u9879", "\u5468\u4F1A", "\u590D\u76D8"])) {
      return "meeting-note" /* MEETING_NOTE */;
    }
    if (this.matchKeywords(text, ["\u8BA1\u5212", "\u6392\u671F", "\u91CC\u7A0B\u7891", "\u4EFB\u52A1", "sprint", "\u8FED\u4EE3"])) {
      return "task-plan" /* TASK_PLAN */;
    }
    if (this.matchKeywords(text, ["\u4E16\u754C\u89C2", "\u8BBE\u5B9A", "\u79CD\u65CF", "\u9B54\u6CD5", "\u89C4\u5219", "\u5386\u53F2\u7EBF"])) {
      return "world-building" /* WORLD_BUILDING */;
    }
    if (this.matchKeywords(text, ["\u603B\u7ED3", "\u9605\u8BFB", "\u8BFB\u4E66", "\u7AE0\u8282", "\u7B14\u8BB0"])) {
      return "reading-note" /* READING_NOTE */;
    }
    if (this.matchKeywords(text, ["\u6982\u5FF5", "\u5B9A\u4E49", "\u89E3\u91CA", "\u662F\u4EC0\u4E48"])) {
      return "concept" /* CONCEPT */;
    }
    if (this.matchKeywords(text, ["\u4EE3\u7801", "\u5B9E\u73B0", "API", "SDK", "\u914D\u7F6E", "\u90E8\u7F72", "debug", "bug"])) {
      return "tech-doc" /* TECH_DOC */;
    }
    if (instruction.includes("?") || instruction.includes("\uFF1F")) {
      return "qa" /* QA */;
    }
    return "unknown" /* UNKNOWN */;
  }
  matchKeywords(text, keywords) {
    return keywords.some((kw) => text.includes(kw.toLowerCase()));
  }
};

