var STYLE_MODIFIERS = {
  "minimal": "\u6781\u7B80\u98CE\u683C\uFF1A\u53EA\u4FDD\u7559\u6838\u5FC3\u4FE1\u606F\uFF0C\u53BB\u9664\u6240\u6709\u5197\u4F59\u3002\u6BB5\u843D\u6781\u77ED\uFF0C\u5927\u91CF\u7559\u767D\u3002",
  "technical": "\u6280\u672F\u6587\u6863\u98CE\u683C\uFF1A\u7CBE\u786E\u3001\u4E25\u8C28\u3001\u4EE3\u7801\u53CB\u597D\u3002\u4F7F\u7528\u4E13\u4E1A\u672F\u8BED\uFF0C\u6807\u6CE8\u7248\u672C\u548C\u517C\u5BB9\u6027\u3002",
  "product": "\u4EA7\u54C1\u6587\u6863\u98CE\u683C\uFF1A\u9762\u5411\u7528\u6237\uFF0C\u6E05\u6670\u7684\u6B65\u9AA4\u548C\u622A\u56FE\u63CF\u8FF0\u4F4D\u3002\u5F3A\u8C03\u7528\u6237\u4EF7\u503C\u3002",
  "academic": "\u5B66\u672F\u98CE\u683C\uFF1A\u4E25\u8C28\u8BBA\u8BC1\uFF0C\u5F15\u7528\u6765\u6E90\uFF0C\u4F7F\u7528\u5B66\u672F\u672F\u8BED\u3002\u903B\u8F91\u94FE\u6761\u5B8C\u6574\u3002",
  "knowledge-base": "\u77E5\u8BC6\u5E93\u98CE\u683C\uFF1A\u6A21\u5757\u5316\u3001\u53EF\u68C0\u7D22\u3001\u5F3A\u94FE\u63A5\u3002\u6BCF\u4E2A\u6BB5\u843D\u72EC\u7ACB\u53EF\u7406\u89E3\u3002",
  "story": "\u53D9\u4E8B\u98CE\u683C\uFF1A\u6709\u6545\u4E8B\u611F\u548C\u6C89\u6D78\u611F\uFF0C\u4F46\u4FDD\u6301\u7ED3\u6784\u5316\u3002\u9002\u5408\u4E16\u754C\u89C2\u548C\u8BBE\u5B9A\u6587\u6863\u3002",
  "dashboard": "\u5361\u7247\u5316\u98CE\u683C\uFF1A\u4FE1\u606F\u5BC6\u5EA6\u9AD8\uFF0C\u4F7F\u7528\u5927\u91CF Callout \u4F5C\u4E3A\u4FE1\u606F\u5361\u7247\u3002\u6BCF\u4E2A\u77E5\u8BC6\u70B9\u4E00\u4E2A Callout\u3002\u9002\u5408\u5FEB\u901F\u626B\u63CF\u3002\u7ED3\u6784\u793A\u4F8B\uFF1A\n> [!abstract] \u6982\u89C8\n> \u5185\u5BB9\n\n> [!info] \u8981\u70B9 1\n> \u5185\u5BB9\n\n> [!tip] \u8981\u70B9 2\n> \u5185\u5BB9"
};
var StructuredPromptBuilder = class {
  constructor(defaultStyle = "knowledge-base") {
    this.defaultStyle = defaultStyle;
  }
  /**
   * 构建完整的 system prompt
   */
  buildSystemPrompt(contentType, style) {
    const template = TEMPLATES[contentType] || TEMPLATES["unknown" /* UNKNOWN */];
    const effectiveStyle = style || this.defaultStyle;
    const parts = [];
    parts.push(template.systemPrompt);
    parts.push(`
\u8F93\u51FA\u98CE\u683C\uFF1A${STYLE_MODIFIERS[effectiveStyle]}`);
    parts.push("\n## \u683C\u5F0F\u89C4\u5219\uFF08\u5FC5\u987B\u9075\u5B88\uFF09\n");
    parts.push(template.formattingRules.map((r, i) => `${i + 1}. ${r}`).join("\n"));
    if (template.calloutRules.length > 0) {
      parts.push("\n## Callout \u4F7F\u7528\u89C4\u5219\n");
      parts.push(template.calloutRules.map((r) => `- ${r}`).join("\n"));
    }
    if (template.mermaidRules.length > 0) {
      parts.push("\n## Mermaid \u56FE\u8868\u89C4\u5219\n");
      parts.push(template.mermaidRules.map((r) => `- ${r}`).join("\n"));
    }
    if (template.markdownStructure.trim()) {
      parts.push("\n## \u63A8\u8350\u6587\u6863\u7ED3\u6784\n");
      parts.push("\u6839\u636E\u5185\u5BB9\u9700\u8981\u9009\u62E9\u5408\u9002\u7684\u7AE0\u8282\uFF08\u4E0D\u5FC5\u5168\u90E8\u4F7F\u7528\uFF09\uFF1A");
      parts.push(template.markdownStructure);
    }
    parts.push(`
## \u8F93\u51FA\u8981\u6C42
`);
    parts.push("\u76F4\u63A5\u8F93\u51FA Markdown \u5185\u5BB9\uFF0C\u4E0D\u8981\u5305\u88F9\u5728 JSON \u6216\u4EE3\u7801\u5757\u4E2D\u3002");
    parts.push("\u4E0D\u8981\u8F93\u51FA\u4EFB\u4F55\u89E3\u91CA\u6027\u524D\u7F00\uFF08\u5982\u300C\u4EE5\u4E0B\u662F...\u300D\uFF09\uFF0C\u76F4\u63A5\u8F93\u51FA\u6B63\u6587\u3002");
    parts.push("\n## \u53CC\u94FE\u89C4\u5219\uFF08\u5FC5\u987B\u9075\u5B88\uFF09\n");
    parts.push("\u6240\u6709\u4E13\u4E1A\u672F\u8BED\u3001\u6982\u5FF5\u540D\u8BCD\u3001\u6280\u672F\u540D\u8BCD\u5FC5\u987B\u7528 Obsidian \u53CC\u94FE\u683C\u5F0F\u5305\u88F9\uFF1A[[\u6982\u5FF5\u540D]]");
    parts.push("\u4F8B\u5982\uFF1A[[TCP]]\u3001[[CAP\u5B9A\u7406]]\u3001[[\u5FAE\u670D\u52A1]]\u3001[[\u4E00\u81F4\u6027]]");
    parts.push("\u8FD9\u662F Obsidian \u77E5\u8BC6\u5E93\u7684\u6838\u5FC3\u7279\u6027\uFF0C\u4E0D\u53EF\u7701\u7565\u3002");
    return parts.join("\n");
  }
  /**
   * 构建 user prompt（包含上下文）
   */
  buildUserPrompt(instruction, ctx) {
    const parts = [];
    if (instruction.trim()) {
      parts.push(`\u3010\u6307\u4EE4\u3011${instruction.trim()}`);
    } else {
      parts.push("\u3010\u6307\u4EE4\u3011\uFF08\u672A\u6307\u5B9A\uFF0C\u8BF7\u6839\u636E\u4E0A\u4E0B\u6587\u667A\u80FD\u5224\u65AD\u5E76\u751F\u6210\u7ED3\u6784\u5316\u5185\u5BB9\uFF09");
    }
    parts.push(`
\u3010\u6587\u4EF6\u3011${ctx.fileName}${ctx.fileType ? ` (type: ${ctx.fileType})` : ""}`);
    if (ctx.selection) {
      parts.push(`
\u3010\u9009\u4E2D\u5185\u5BB9\u3011
${ctx.selection}`);
    }
    if (ctx.sectionName) {
      parts.push(`
\u3010\u5F53\u524D\u7AE0\u8282\u3011${ctx.sectionName}${ctx.sectionEmpty ? "\uFF08\u7A7A\uFF0C\u9700\u8981\u8865\u5168\uFF09" : ""}`);
    }
    if (!ctx.selection && ctx.cursorLineBefore) {
      parts.push(`
\u3010\u5149\u6807\u524D\u5185\u5BB9\u3011
${ctx.cursorLineBefore.slice(-500)}`);
    }
    if (ctx.fileContent) {
      const content = ctx.fileContent.length > 2e3 ? ctx.fileContent.slice(0, 2e3) + "\n...\uFF08\u7701\u7565\uFF09" : ctx.fileContent;
      parts.push(`
\u3010\u6587\u4EF6\u5168\u6587\u3011
${content}`);
    }
    return parts.join("\n");
  }
};

// src/ai/formatter/MarkdownBeautifier.ts
var MarkdownBeautifier = class {
  constructor(knownConcepts) {
    this.knownConcepts = new Set(knownConcepts != null ? knownConcepts : []);
  }
  /** 执行所有美化步骤 */
  beautify(content) {
    let result = content;
    result = this.splitLongParagraphs(result);
    result = this.convertCallouts(result);
    result = this.insertVisualBreaks(result);
    result = this.autoLinkConcepts(result);
    result = this.cleanupSpacing(result);
    return result;
  }
  /**
   * 1. 长段落拆分
   * 超过 4 行的连续文本段落，在句号处拆分
   */
  splitLongParagraphs(content) {
    const lines = content.split("\n");
    const result = [];
    let paragraphLines = [];
    const flushParagraph = () => {
      if (paragraphLines.length <= 4) {
        result.push(...paragraphLines);
      } else {
        const text = paragraphLines.join("\n");
        const sentences = text.split(/(?<=[。！？.!?])\s*/);
        let chunk = [];
        let lineCount = 0;
        for (const sentence of sentences) {
          chunk.push(sentence);
          lineCount += Math.ceil(sentence.length / 40);
          if (lineCount >= 3) {
            result.push(chunk.join(""));
            result.push("");
            chunk = [];
            lineCount = 0;
          }
        }
        if (chunk.length > 0)
          result.push(chunk.join(""));
      }
      paragraphLines = [];
    };
    for (const line of lines) {
      const isStructural = /^(#|>|\||-|\d+\.|```|---|\s*$)/.test(line);
      if (isStructural) {
        flushParagraph();
        result.push(line);
      } else {
        paragraphLines.push(line);
      }
    }
    flushParagraph();
    return result.join("\n");
  }
  /**
   * 2. 自动 Callout 转换
   * 识别特定模式并转为 Obsidian Callout
   */
  convertCallouts(content) {
    let result = content;
    result = result.replace(
      /^(风险|注意|警告|⚠️)[:：]\s*(.+)$/gm,
      "> [!warning] $1\n> $2"
    );
    result = result.replace(
      /^(建议|技巧|提示|💡)[:：]\s*(.+)$/gm,
      "> [!tip] $1\n> $2"
    );
    result = result.replace(
      /^(总结|结论|摘要|核心)[:：]\s*(.+)$/gm,
      "> [!summary] $1\n> $2"
    );
    result = result.replace(
      /^(示例|例如|例子)[:：]\s*(.+)$/gm,
      "> [!example] $1\n> $2"
    );
    result = result.replace(
      /^(决策|决定)[:：]\s*(.+)$/gm,
      "> [!abstract] $1\n> $2"
    );
    return result;
  }
  /**
   * 3. 插入视觉断点
   * 每 250-350 字（约 3-4 段）如果没有标题/callout/分隔线，插入分隔
   */
  insertVisualBreaks(content) {
    const lines = content.split("\n");
    const result = [];
    let charsSinceBreak = 0;
    for (const line of lines) {
      const isBreak = /^(#{1,6}\s|>|---|\||\s*$|```mermaid)/.test(line);
      if (isBreak) {
        charsSinceBreak = 0;
      } else {
        charsSinceBreak += line.length;
      }
      result.push(line);
      if (charsSinceBreak > 300 && !isBreak) {
        result.push("");
        charsSinceBreak = 0;
      }
    }
    return result.join("\n");
  }
  /**
   * 4. 自动双链
   * 将已知概念转为 [[双链]] 格式
   */
  autoLinkConcepts(content) {
    if (this.knownConcepts.size === 0)
      return content;
    let result = content;
    const sorted = [...this.knownConcepts].sort((a, b) => b.length - a.length);
    for (const concept of sorted) {
      if (concept.length < 2)
        continue;
      const regex = new RegExp(
        `(?<!\\[\\[)(?<!\\w)${this.escapeRegex(concept)}(?!\\w)(?!\\]\\])`,
        "g"
      );
      const lines = result.split("\n");
      let inCodeBlock = false;
      result = lines.map((line) => {
        if (line.startsWith("```"))
          inCodeBlock = !inCodeBlock;
        if (inCodeBlock)
          return line;
        if (/^#/.test(line))
          return line;
        if (/^>/.test(line))
          return line.replace(regex, `[[${concept}]]`);
        return line.replace(regex, `[[${concept}]]`);
      }).join("\n");
    }
    return result;
  }
  /**
   * 5. 清理多余空行
   */
  cleanupSpacing(content) {
    return content.replace(/\n{4,}/g, "\n\n\n");
  }
  escapeRegex(str) {
    return str.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  }
};

// src/ai/formatter/ReadableLayoutEngine.ts
var ReadableLayoutEngine = class {
  /**
   * 优化文档布局
   */
  optimize(content) {
    let result = content;
    result = this.enforceHeadingDepth(result);
    result = this.ensureTLDR(result);
    result = this.balanceDensity(result);
    result = this.addSectionSpacing(result);
    return result;
  }
  /**
   * 标题深度控制
   * 禁止超过 H3，H4+ 转为加粗或 Callout
   */
  enforceHeadingDepth(content) {
    const lines = content.split("\n");
    return lines.map((line) => {
      if (/^####\s+(.+)/.test(line)) {
        return `**${line.replace(/^####\s+/, "")}**`;
      }
      if (/^#{5,6}\s+(.+)/.test(line)) {
        return `**${line.replace(/^#{5,6}\s+/, "")}**`;
      }
      return line;
    }).join("\n");
  }
  /**
   * 确保文档顶部有 TLDR/摘要
   * 如果文档有 H1 但没有紧跟 summary callout，不强制添加（由 AI 生成）
   * 这里只检查格式：如果有 > [!summary] 确保它在顶部
   */
  ensureTLDR(content) {
    const lines = content.split("\n");
    const summaryIdx = lines.findIndex((l) => /^>\s*\[!summary\]/.test(l));
    if (summaryIdx <= 0)
      return content;
    const h1Idx = lines.findIndex((l) => /^#\s+/.test(l));
    if (h1Idx < 0)
      return content;
    if (summaryIdx > h1Idx + 3) {
      const summaryLines = [];
      let i = summaryIdx;
      while (i < lines.length && (lines[i].startsWith(">") || lines[i].trim() === "")) {
        if (lines[i].startsWith(">"))
          summaryLines.push(lines[i]);
        else if (summaryLines.length > 0)
          break;
        i++;
      }
      lines.splice(summaryIdx, summaryLines.length);
      lines.splice(h1Idx + 1, 0, "", ...summaryLines, "");
    }
    return lines.join("\n");
  }
  /**
   * 平衡信息密度
   * 如果连续多个列表项（>8），插入分组标记
   */
  balanceDensity(content) {
    const lines = content.split("\n");
    const result = [];
    let consecutiveListItems = 0;
    for (const line of lines) {
      if (/^[-*]\s/.test(line)) {
        consecutiveListItems++;
        if (consecutiveListItems > 0 && consecutiveListItems % 6 === 0) {
          result.push("");
        }
      } else {
        consecutiveListItems = 0;
      }
      result.push(line);
    }
    return result.join("\n");
  }
  /**
   * 章节间距
   * 确保每个 ## 标题前有足够空行
   */
  addSectionSpacing(content) {
    return content.replace(/([^\n])\n(##\s)/g, "$1\n\n$2");
  }
};

// src/ai/AIAssistant.ts
var AIAssistant = class {
  constructor(settings, outputStyle = "knowledge-base", knownConcepts = []) {
    this.settings = settings;
    this.outputStyle = outputStyle;
    this.knownConcepts = knownConcepts;
    this.classifier = new ContentClassifier();
    this.promptBuilder = new StructuredPromptBuilder(outputStyle);
    this.llm = new LLMClient(settings);
  }
  async run(instruction, ctx) {
    this.llm.ensureApiKey();
    const contentType = this.classifier.classify({
      instruction,
      fileName: ctx.fileName,
      filePath: ctx.fileName,
      // 简化：用 fileName 代替完整路径
      fileType: ctx.fileType,
      selection: ctx.selection
    });
    const systemPrompt = this.promptBuilder.buildSystemPrompt(contentType, this.outputStyle);
    const userPrompt = this.promptBuilder.buildUserPrompt(instruction, ctx);
    const modeInstruction = this.buildModeInstruction(ctx);
    const fullUserPrompt = userPrompt + "\n\n" + modeInstruction;
    const raw = await this.callAPI(systemPrompt, fullUserPrompt);
    const { mode, content } = this.parseResponse(raw, ctx);
    const beautifier = new MarkdownBeautifier(this.knownConcepts);
    const beautified = beautifier.beautify(content);
    const layoutEngine = new ReadableLayoutEngine();
    const final = layoutEngine.optimize(beautified);
    return {
      mode,
      content: final,
      explanation: this.generateExplanation(mode, contentType)
    };
  }
  /** 美化已有文档（不调用 AI，只做格式化） */
  beautifyContent(content) {
    const beautifier = new MarkdownBeautifier(this.knownConcepts);
    const beautified = beautifier.beautify(content);
    const layoutEngine = new ReadableLayoutEngine();
    return layoutEngine.optimize(beautified);
  }
  buildModeInstruction(ctx) {
    const parts = ["\u3010\u8F93\u51FA\u6A21\u5F0F\u5224\u65AD\u3011"];
    if (ctx.selection) {
      parts.push("\u6709\u9009\u4E2D\u5185\u5BB9\u3002\u5982\u679C\u6307\u4EE4\u662F\u6539\u5199/\u6269\u5199/\u7FFB\u8BD1\uFF0C\u8F93\u51FA\u5E94\u66FF\u6362\u9009\u4E2D\u5185\u5BB9\uFF08\u5728\u7B2C\u4E00\u884C\u5199 `<!-- mode:replace -->`\uFF09\u3002");
      parts.push("\u5982\u679C\u662F\u751F\u6210\u65B0\u5185\u5BB9\uFF08\u56FE\u8868\u3001\u89E3\u91CA\u7B49\uFF09\uFF0C\u8F93\u51FA\u5E94\u63D2\u5165\u5230\u9009\u4E2D\u5185\u5BB9\u4E0B\u65B9\uFF08\u5728\u7B2C\u4E00\u884C\u5199 `<!-- mode:insert -->`\uFF09\u3002");
    } else if (ctx.sectionEmpty && ctx.sectionName) {
      parts.push(`\u5149\u6807\u5728\u7A7A\u7AE0\u8282"${ctx.sectionName}"\u5185\u3002\u8F93\u51FA\u5E94\u586B\u5145\u8BE5\u7AE0\u8282\uFF08\u5728\u7B2C\u4E00\u884C\u5199 \`<!-- mode:insert -->\`\uFF09\u3002`);
    } else if (ctx.cursorLineBefore) {
      parts.push("\u65E0\u9009\u4E2D\u5185\u5BB9\u3002\u8F93\u51FA\u5E94\u63D2\u5165\u5230\u5149\u6807\u4F4D\u7F6E\uFF08\u5728\u7B2C\u4E00\u884C\u5199 `<!-- mode:insert -->`\uFF09\u3002");
    } else {
      parts.push("\u8F93\u51FA\u8FFD\u52A0\u5230\u6587\u4EF6\u672B\u5C3E\uFF08\u5728\u7B2C\u4E00\u884C\u5199 `<!-- mode:append -->`\uFF09\u3002");
    }
    parts.push("\u5982\u679C\u53EA\u662F\u56DE\u7B54\u95EE\u9898/\u89E3\u91CA\uFF08\u4E0D\u9700\u8981\u4FEE\u6539\u6587\u4EF6\uFF09\uFF0C\u5728\u7B2C\u4E00\u884C\u5199 `<!-- mode:show -->`\u3002");
    parts.push("\n\u6CE8\u610F\uFF1Amode \u6CE8\u91CA\u5FC5\u987B\u662F\u8F93\u51FA\u7684\u7B2C\u4E00\u884C\uFF0C\u540E\u9762\u7D27\u8DDF\u6B63\u6587\u5185\u5BB9\u3002");
    return parts.join("\n");
  }
  async callAPI(systemPrompt, userPrompt) {
    return this.llm.chat({ systemPrompt, userPrompt, temperature: 0.5 });
  }
  parseResponse(raw, ctx) {
    const modeMatch = raw.match(/^<!--\s*mode:(replace|insert|append|show)\s*-->\s*\n?/);
    let mode;
    let content;
    if (modeMatch) {
      mode = modeMatch[1];
      content = raw.slice(modeMatch[0].length).trim();
    } else {
      if (ctx.selection) {
        mode = "replace";
      } else if (ctx.sectionEmpty) {
        mode = "insert";
      } else {
        mode = "insert";
      }
      content = raw.trim();
    }
    return { mode, content };
  }
  generateExplanation(mode, contentType) {
    const modeLabels = {
      replace: "\u66FF\u6362\u9009\u4E2D\u5185\u5BB9",
      insert: "\u63D2\u5165\u5230\u5149\u6807\u4F4D\u7F6E",
      append: "\u8FFD\u52A0\u5230\u6587\u4EF6\u672B\u5C3E",
      show: "\u4EC5\u5C55\u793A"
    };
    return `${modeLabels[mode]}\uFF08${contentType}\uFF09`;
  }
};

