var import_obsidian17 = require("obsidian");
var QuestionModal = class extends import_obsidian17.Modal {
  constructor(app, onSubmit) {
    super(app);
    this.question = "";
    this.onSubmit = onSubmit;
  }
  onOpen() {
    const { contentEl } = this;
    new import_obsidian17.Setting(contentEl).setName("\u5411 DeepSeek \u63D0\u95EE").setHeading();
    const textArea = contentEl.createEl("textarea", {
      attr: {
        placeholder: "\u8F93\u5165\u4F60\u7684\u95EE\u9898...",
        rows: "4"
      },
      cls: "istart-question-textarea"
    });
    textArea.addEventListener("input", () => {
      this.question = textArea.value;
    });
    textArea.addEventListener("keydown", (e) => {
      if ((e.ctrlKey || e.metaKey) && e.key === "Enter") {
        this.submit();
      }
    });
    new import_obsidian17.Setting(contentEl).addButton(
      (btn) => btn.setButtonText("\u63D0\u95EE (Ctrl+Enter)").setCta().onClick(() => this.submit())
    ).addButton(
      (btn) => btn.setButtonText("\u53D6\u6D88").onClick(() => this.close())
    );
    setTimeout(() => textArea.focus(), 50);
  }
  submit() {
    const q = this.question.trim();
    if (!q)
      return;
    this.close();
    this.onSubmit(q);
  }
  onClose() {
    this.contentEl.empty();
  }
};

