// src/features/dashboard/KnowledgeDebtModal.ts
var import_obsidian19 = require("obsidian");
var KnowledgeDebtModal = class extends import_obsidian19.Modal {
  constructor(app, index, onAction) {
    super(app);
    this.index = index;
    this.onAction = onAction;
  }
  onOpen() {
    this.titleEl.setText("\u{1F4CA} \u77E5\u8BC6\u503A\u52A1\u770B\u677F");
    this.stats = this.computeStats();
    this.render();
  }
  render() {
    const { contentEl } = this;
    contentEl.empty();
    const total = this.stats.emptyConcepts.length + this.stats.orphanQuestions.length + this.stats.unfinishedReadings.length + this.stats.staleNotes.length;
    if (total === 0) {
      contentEl.createEl("p", { text: "\u{1F389} \u4F60\u7684\u77E5\u8BC6\u5E93\u5F88\u5065\u5EB7\uFF0C\u6CA1\u6709\u53D1\u73B0\u5F85\u5904\u7406\u7684\u77E5\u8BC6\u503A\u52A1\u3002" });
      new import_obsidian19.Setting(contentEl).addButton((btn) => btn.setButtonText("\u5173\u95ED").onClick(() => this.close()));
      return;
    }
    contentEl.createEl("p", {
      text: `\u53D1\u73B0 ${total} \u9879\u9700\u8981\u5173\u6CE8\u7684\u77E5\u8BC6\u503A\u52A1\uFF1A`,
      attr: { style: "color: var(--text-muted); margin-bottom: 12px;" }
    });
    this.renderSection(
      contentEl,
      `\u{1F4DD} \u7A7A\u6982\u5FF5\u9875 (${this.stats.emptyConcepts.length})`,
      this.stats.emptyConcepts,
      "\u8865\u5168\u8FD9\u4E9B\u6982\u5FF5",
      "complete-concepts"
    );
    this.renderSection(
      contentEl,
      `\u2753 \u5B64\u7ACB\u95EE\u9898 (${this.stats.orphanQuestions.length})`,
      this.stats.orphanQuestions,
      "\u5206\u7C7B\u8FD9\u4E9B\u95EE\u9898",
      "classify-questions"
    );
    this.renderSection(
      contentEl,
      `\u{1F4D6} \u672A\u5B8C\u6210\u9605\u8BFB\u7AE0\u8282 (${this.stats.unfinishedReadings.length})`,
      this.stats.unfinishedReadings,
      null,
      null
    );
    this.renderSection(
      contentEl,
      `\u{1F578} \u957F\u671F\u672A\u66F4\u65B0\u8349\u7A3F (${this.stats.staleNotes.length})`,
      this.stats.staleNotes,
      null,
      null
    );
    new import_obsidian19.Setting(contentEl).addButton(
      (btn) => btn.setButtonText("\u5173\u95ED").onClick(() => this.close())
    );
  }
  renderSection(container, title, entries, actionLabel, actionId) {
    if (entries.length === 0)
      return;
    const section = container.createDiv({ attr: { style: "margin-bottom: 16px;" } });
    section.createEl("h4", { text: title, attr: { style: "margin: 8px 0 4px 0;" } });
    const list = section.createDiv({
      attr: { style: "max-height: 120px; overflow-y: auto; padding-left: 12px; font-size: 13px;" }
    });
    const shown = entries.slice(0, 15);
    for (const entry of shown) {
      list.createEl("div", {
        text: `\u2022 ${entry.basename}${entry.domain ? ` [${entry.domain}]` : ""}`,
        attr: { style: "padding: 1px 0; color: var(--text-normal);" }
      });
    }
    if (entries.length > 15) {
      list.createEl("div", {
        text: `...\u8FD8\u6709 ${entries.length - 15} \u9879`,
        attr: { style: "color: var(--text-muted); font-style: italic;" }
      });
    }
    if (actionLabel && actionId && this.onAction) {
      new import_obsidian19.Setting(section).addButton(
        (btn) => btn.setButtonText(actionLabel).onClick(() => {
          this.close();
          this.onAction(actionId, entries);
        })
      );
    }
  }
  computeStats() {
    const now = Date.now();
    const NINETY_DAYS = 90 * 24 * 60 * 60 * 1e3;
    const emptyConcepts = this.index.getByType("concept").filter((e) => e.status === "empty" || e.status === "pending");
    const allQuestions = this.index.getByType("question");
    const orphanQuestions = allQuestions.filter((e) => {
      return e.backlinks.length === 0 && e.concepts.length === 0;
    });
    const unfinishedReadings = this.index.getAll().filter((e) => {
      return e.path.includes("Reading/") && e.type !== "domain-index" && e.status !== "completed" && e.headings.some((h) => h.includes("\u7B14\u8BB0") || h.includes("\u95EE\u9898"));
    });
    const staleNotes = this.index.getAll().filter((e) => {
      return e.status === "draft" && now - e.mtime > NINETY_DAYS;
    });
    return { emptyConcepts, orphanQuestions, unfinishedReadings, staleNotes };
  }
  onClose() {
    this.contentEl.empty();
  }
};

